        const int Cols = 16, CellW = 98, CellH = 74, AtlasW = 1568, AtlasH = 1184;

        public static int Count => Codes.Length;
        public static int IndexOf(string code) { for (int i = 0; i < Codes.Length; i++) if (Codes[i] == code) return i; return 0; }
        public static string Name(int i) => (Settings.Turkish ? NamesTR : NamesEN)[Mathf.Clamp(i, 0, Codes.Length - 1)];
        public static string Name(string code) => Name(IndexOf(code));

        /// UV rect of a flag inside the atlas (half-pixel inset so neighbours never bleed in).
        public static Rect UV(int i)
        {
            i = Mathf.Clamp(i, 0, Codes.Length - 1);
            int c = i % Cols, r = i / Cols;
            float x = c * CellW + 1.5f, y = r * CellH + 1.5f, w = 95f, h = 71f;
            return new Rect(x / AtlasW, 1f - (y + h) / AtlasH, w / AtlasW, h / AtlasH);
        }

        /// Puts a flag on a RawImage (no-op if the atlas is missing).
        public static void Apply(RawImage img, string code)
        {
            if (img == null) return;
            var tex = Z47Refs.I != null ? Z47Refs.I.flagAtlas : null;
            img.enabled = tex != null && !string.IsNullOrEmpty(code);
            if (!img.enabled) return;
            img.texture = tex; img.uvRect = UV(IndexOf(code));
        }

        /// A small flag image (4:3) under `parent`.
        public static RawImage Make(Transform parent, string name, string code, Vector2 anchor, Vector2 pos, float height)
        {
            var r = UIK.Rect(parent, name, anchor, anchor, pos, new Vector2(height * 4f / 3f, height));
            var img = r.gameObject.AddComponent<RawImage>(); img.raycastTarget = false;
            Apply(img, code);
            return img;
        }

